import React, { useEffect, useState } from "react";

const ProfessorDetalhes = ({ id }) => {
  const [professor, setProfessor] = useState(null); // Estado para armazenar os dados do professor
  const [cursosDisponiveis, setCursosDisponiveis] = useState([]); // Estado para armazenar cursos disponíveis
  const [cursoId, setCursoId] = useState(""); // Estado para armazenar o curso selecionado
  const [editMode, setEditMode] = useState(false); // Estado para determinar se estamos em modo de edição

  // Função para buscar o professor e os cursos associados
  useEffect(() => {
    // Função para buscar as informações do professor
    const fetchProfessor = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessor(dados); // Agora inclui os cursos associados
        } else {
          console.error("Erro ao buscar professor");
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    // Função para buscar os cursos disponíveis
    const fetchCursosDisponiveis = async () => {
      try {
        const resposta = await fetch("http://localhost:5000/cursos");
        if (resposta.ok) {
          const cursos = await resposta.json();
          setCursosDisponiveis(cursos);
        } else {
          console.error("Erro ao buscar cursos");
        }
      } catch (error) {
        console.error("Erro na requisição de cursos:", error);
      }
    };

    fetchProfessor();
    fetchCursosDisponiveis();
  }, [id]);

  // Função para lidar com a mudança no curso selecionado
  const handleCursoChange = (e) => {
    setCursoId(e.target.value);
  };

  // Função para adicionar um curso ao professor
  const handleAddCurso = async () => {
    if (!cursoId) {
      alert("Selecione um curso para adicionar.");
      return;
    }

    try {
      const resposta = await fetch(
        `http://localhost:5000/professores/${id}/cursos`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ cursoId }),
        }
      );

      if (resposta.ok) {
        const novaRelacao = await resposta.json();
        setProfessor((prevProfessor) => ({
          ...prevProfessor,
          cursos: [...prevProfessor.cursos, novaRelacao.relacao.curso], // Adiciona o curso à lista do professor
        }));
        setCursoId(""); // Limpa o curso selecionado
      } else {
        console.error("Erro ao adicionar curso");
      }
    } catch (error) {
      console.error("Erro na requisição de adicionar curso:", error);
    }
  };

  if (!professor) {
    return <p>Carregando professor...</p>;
  }

  return (
    <div className="container">
      <h2>Detalhes do Professor</h2>

      <div>
        <h4>Informações Pessoais</h4>
        <p>
          <strong>Nome:</strong> {professor.nome}
        </p>
        <p>
          <strong>Email:</strong> {professor.email}
        </p>
        <p>
          <strong>Morada:</strong> {professor.morada}
        </p>
        <p>
          <strong>Contacto:</strong> {professor.contacto}
        </p>
        <p>
          <strong>Estado:</strong> {professor.estado}
        </p>

        {/* Toggle para editar */}
        <button onClick={() => setEditMode(!editMode)}>
          {editMode ? "Cancelar Edição" : "Editar Professor"}
        </button>
      </div>

      <div className="w-50 ps-4">
        <label className="fw-bold">Cursos que Leciona</label>
        {professor.cursos && professor.cursos.length > 0 ? (
          professor.cursos.map((curso, index) => (
            <div key={index} className="input-group mb-2">
              <input
                type="text"
                className="form-control"
                value={curso.nome}
                disabled={!editMode}
              />
            </div>
          ))
        ) : (
          <p>Este professor não leciona cursos no momento.</p>
        )}

        {editMode && (
          <>
            <div className="mb-3">
              <select
                className="form-select"
                value={cursoId}
                onChange={handleCursoChange}
              >
                <option value="">Selecione um curso</option>
                {cursosDisponiveis.map((curso) => (
                  <option key={curso.id} value={curso.id}>
                    {curso.nome}
                  </option>
                ))}
              </select>
            </div>
            <button
              className="btn btn-outline-secondary mt-2"
              onClick={handleAddCurso}
            >
              Adicionar Curso
            </button>
          </>
        )}
      </div>
    </div>
  );
};

export default ProfessorDetalhes;
